const CACHE_PREFIX=`diario-de-bordo-${self.registration.scope}-`,CACHE_NAME=`${CACHE_PREFIX}performance-v1`,ASSETS=["./","./index.html","./style.css","./script.js","./manifest.json","./icons/brand.webp","./icons/icon-192.png","./icons/icon-512.png"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(ASSETS)).then(()=>self.skipWaiting()))}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.filter(e=>e.startsWith(CACHE_PREFIX)&&e!==CACHE_NAME).map(e=>caches.delete(e)))).then(()=>self.clients.claim()))}),self.addEventListener("fetch",e=>{const t=new URL(e.request.url);"GET"===e.request.method&&t.origin===self.location.origin&&t.href.startsWith(self.registration.scope)&&e.respondWith((async()=>{const t=await caches.open(CACHE_NAME);if("navigate"===e.request.mode)try{return await fetch(e.request)}catch{return await t.match("./index.html")}return await t.match(e.request)||fetch(e.request)})())});